// App code: the click action, and setting loading and disabled while work runs.
import type { Example } from "../example.ts"
import { html, type TemplateResult } from "lit-html"

export type ButtonVariant = "primary" | "default" | "invisible" | "danger" | "link" | "inactive"
export type ButtonSize = "small" | "medium" | "large"

export type ButtonProps = {
  label: string
  variant: ButtonVariant
  size?: ButtonSize
  block?: boolean
  disabled?: boolean
  loading?: boolean
  onClick?: (event: MouseEvent) => void
  class?: string
}

const base =
  "inline-flex items-center justify-center gap-2 font-medium rounded-control cursor-pointer select-none transition duration-fast focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-0 active:scale-98 disabled:pointer-events-none disabled:opacity-50"

const fills: Record<ButtonVariant, string> = {
  primary: "bg-accent text-on-fill hover:bg-accent-strong",
  default: "bg-subtle text-fg hover:bg-line",
  invisible: "bg-transparent text-fg hover:bg-subtle",
  danger: "bg-danger-fg text-on-fill hover:opacity-90",
  link: "bg-transparent text-accent hover:underline",
  inactive: "bg-surface text-muted border border-solid border-line opacity-60 cursor-not-allowed",
}

// min-h, not h: apps put these classes on buttons with two-line labels.
const sizes: Record<ButtonSize, string> = {
  small: "min-h-tab px-2 text-xs",
  medium: "min-h-touch px-4 py-2.5 text-sm",
  large: "min-h-touch px-4 py-2.5 text-base",
}

export type ButtonLook = { variant: ButtonVariant; size?: ButtonSize; block?: boolean }

/** The classes button() puts on its <button>; apps put them on their own <a>, <label> or form <button>. */
export function buttonClass(look: ButtonLook): string {
  const classes = [base, fills[look.variant], sizes[look.size ?? "medium"]]
  if (look.block === true) classes.push("w-full")
  return classes.join(" ")
}

export function button(props: ButtonProps): TemplateResult {
  const unavailable = props.loading === true
  const classes = ["relative", buttonClass(props)]
  if (props.class !== undefined) classes.push(props.class)
  return html`<button
    type="button"
    class=${classes.join(" ")}
    ?disabled=${props.disabled === true}
    aria-disabled=${props.loading === true ? "true" : "false"}
    data-loading=${props.loading === true ? "true" : "false"}
    @click=${unavailable ? undefined : props.onClick}
  >${props.loading === true
      ? html`<span class="absolute inline-block w-4 h-4 border-2 border-solid border-current border-t-transparent rounded-full animate-spin" aria-hidden="true"></span><span class="text-transparent">${props.label}</span><span class="sr-only"> (loading)</span>`
      : props.label}</button>`
}

export const examples: Example[] = [
  { label: "primary", render: () => button({ label: "Save", variant: "primary" }) },
  { label: "default", render: () => button({ label: "Cancel", variant: "default" }) },
  { label: "danger", render: () => button({ label: "Remove", variant: "danger" }) },
  { label: "invisible", render: () => button({ label: "Not now", variant: "invisible" }) },
  { label: "link", render: () => button({ label: "Learn more", variant: "link" }) },
  { label: "inactive", render: () => button({ label: "Save", variant: "inactive" }) },
  { label: "small", render: () => button({ label: "Save", variant: "primary", size: "small" }) },
  { label: "medium", render: () => button({ label: "Save", variant: "primary", size: "medium" }) },
  { label: "large", render: () => button({ label: "Save", variant: "primary", size: "large" }) },
  { label: "block", render: () => button({ label: "Save", variant: "primary", block: true }) },
  { label: "disabled", render: () => button({ label: "Save", variant: "primary", disabled: true }) },
  { label: "loading", render: () => button({ label: "Save", variant: "primary", loading: true }) },
]
